ALTER TABLE a ADD COLUMN IF NOT EXISTS e text DEFAULT 'a,b';
ALTER TABLE "my table" ADD COLUMN IF NOT EXISTS f int;
ALTER TABLE a ADD COLUMN IF NOT EXISTS "g,h" int, ADD COLUMN IF NOT EXISTS i int;
DO $$ BEGIN CREATE TYPE k AS ENUM ('x'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'c;x') THEN
    ALTER TABLE a ADD CONSTRAINT c CHECK (id > 0);
  END IF;
  IF NOT EXISTS (SELECT 1) THEN
    CREATE INDEX ix2 ON a (id);
  END IF;
END
$$;
